solution:
use xiom.io;

type Account = {
  id: Int;
  owner: Str;
  balance: Float64;
  invariant: balance >= 0.0;
}

fn open_account(id: Int, owner: Str) -> Account
  requires: id > 0;
  ensures: result.balance == 0.0;
{
  return Account{ id: id, owner: owner, balance: 0.0 };
}

fn deposit(account: &mut Account, amount: Float64)
  requires: amount > 0.0;
  ensures: account.balance == account@pre.balance + amount;
{
  account.balance = account.balance + amount;
}

fn withdraw(account: &mut Account, amount: Float64)
  requires: amount > 0.0;
  requires: amount <= account.balance;
  ensures: account.balance == account@pre.balance - amount;
{
  account.balance = account.balance - amount;
}

fn transfer(from: &mut Account, to: &mut Account, amount: Float64)
  requires: amount > 0.0;
  requires: amount <= from.balance;
  ensures: from.balance == from@pre.balance - amount;
  ensures: to.balance == to@pre.balance + amount;
{
  from.balance = from.balance - amount;
  to.balance = to.balance + amount;
}

fn print_statement(account: &Account) {
  io.println("Account #" + account.id.to_str() + " (" + account.owner.to_str() + "): $" + account.balance.to_str());
}

fn add_interest(account: &mut Account, rate: Float64)
  requires: rate > 0.0;
  ensures: account.balance == account@pre.balance * (1.0 + rate);
{
  let interest = account.balance * rate;
  account.balance = account.balance + interest;
}

fn main() -> Int {
  var a1 = open_account(1, "Alice");
  var a2 = open_account(2, "Bob");
  deposit(&mut a1, 1000.0);
  transfer(&mut a1, &mut a2, 250.0);
  print_statement(&a1);
  print_statement(&a2);
  add_interest(&mut a2, 0.05);
  print_statement(&a2);
  return a2.balance as Int;
}
